// Typedef for a function pointer
// Returns int, takes (char*, int)
typedef int (*ValidatorFunc)(const char*, int);

struct ConfigState {
    int max_len;
};

struct ProtocolHandler {
    // Nested struct definition
    struct ConfigState cfg;

    // Function pointer member
    ValidatorFunc validate;

    float timeout_sec;
};

// Example usage
int check_data(const char* data, int len) { return len > 0; }

struct ProtocolHandler P = {
    .cfg = { .max_len = 1024 },
    .validate = check_data,
    .timeout_sec = 5.0f
};
